INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000047',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about money and personal finances in Kannada","Use hana and rupai correctly","Discuss income, savings, and expenses"],"explanation":{"intro":"Money and finances vocabulary covers how to discuss income, savings, spending, and financial situations in Kannada.","culturalNote":"Money culture in Karnataka: the word hana (money) is Kannada — rupai is used for the currency unit (rupee). Kannadigas have a reputation for being frugal and value-conscious (''jenu madda'' — like a honeybee — hardworking and accumulating). Savings: fixed deposit (FD), recurring deposit (RD), PPF (Public Provident Fund), gold savings (very popular — gold wedding jewelry is an important financial asset). Investment: mutual funds (mutual fund), SIP (Systematic Investment Plan — very popular in Bengaluru''s middle class). Real estate: apartment buying in Bengaluru is a major financial goal. Gold: buying gold on Akshaya Tritiya (auspicious day for gold buying). Chit fund (chitty): informal savings group — 10 people put in 10,000 each month, one person gets the whole amount each month (rotating credit association — common in Karnataka and Tamil Nadu). EMI (Equated Monthly Installment): very common for big purchases."},"examples":[{"sentence":"Naanu pratimaasa swalpa hana ulisi muDugutte — FD alli haakuttini.","english":"I save a little money every month — I put it in a Fixed Deposit."},{"sentence":"Ee maney koDuvudu naakke thakku doDDa hana aagutte, EMI beku.","english":"Buying this house costs me quite a lot of money, I will need an EMI."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss money, savings, and financial matters in Kannada."}}',
'{"items":[{"word":"hana","translation":"money","transliteration":"hana","pronunciation":"HA-na","example":"hana beku"},{"word":"rupai","translation":"rupee (currency unit)","transliteration":"rupai","pronunciation":"ru-PAI","example":"nooRu rupai"},{"word":"ulisi muDu","translation":"save (money) — keep aside","transliteration":"ulisi muDu","pronunciation":"u-li-SI MU-Du","example":"hana ulisi muDuttini"},{"word":"kharchu","translation":"expense/expenditure","transliteration":"kharchu","pronunciation":"KHAR-chu","example":"kharchu jaasthi"},{"word":"sambhavana","translation":"salary/income","transliteration":"sambhavana","pronunciation":"sam-BHA-va-na","example":"channa sambhavana"},{"word":"saali","translation":"loan/debt","transliteration":"saali","pronunciation":"SAA-li","example":"saali tirisi"}]}',
'{"title":"Naanu hana ulisi muDuttini — saving money vocabulary in Kannada","pattern":"Naanu hana ulisi muDuttini = I save money. Pratimaasa = every month. Kharchu jaasthi aagutte = expenses are too much. Hana beku = need money. Sambhavana kammagi aagutte = salary is less. Saali tirisabeku = need to repay a loan. Budget maadu = make a budget.","explanation":"Money vocabulary in Kannada: hana (money), rupai (rupee), paishe (paisa — 1/100 of a rupee). Savings: ulisi muDu (save — ulisi = having kept aside, muDu = put/keep). Income: sambhavana (salary), aadaaya (income — general), laabha (profit — in business). Expense: kharchu (expense), vyaya (expenditure). Loan: saali (debt/loan), bank loan (bank loan). Investment: investment maadu (invest). Sufficient: hana saakaagithe (money is enough — saakaagithe = if it is enough). Not enough: hana kammagi ide (money is less/not enough). Prices: daruvoo jaasthi aagutte (prices have gone up — daruvoo = prices). EMI: EMI kaTTabeku (need to pay EMI).","examples":[{"sentence":"Nanna kharchu naanu nambida kante jaasthi aayitu, budget revise maadabeku.","english":"My expenses became more than I expected, I need to revise the budget."},{"sentence":"Pratimaasa naanu aidu saavira rupai FD alli haakuttini.","english":"Every month I put five thousand rupees in a Fixed Deposit."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hana means?","options":["money","rupee","salary","savings"],"correctAnswer":"money"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I save a little money every month — I put it in a Fixed Deposit.","options":["Naanu pratimaasa swalpa hana ulisi muDugutte — FD alli haakuttini.","Naanu pratidinaa swalpa hana ulisi muDugutte — FD alli haakuttini.","Naanu pratimaasa jaasthi hana ulisi muDugutte — FD alli haakuttini.","Avanu pratimaasa swalpa hana ulisi muDuguttaane — FD alli haakuttaane."],"correctAnswer":"Naanu pratimaasa swalpa hana ulisi muDugutte — FD alli haakuttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Pratimaasa naanu aidu saavira rupai FD alli ___ .","options":["haakuttini","tEgeyuttini","ulisuttini","maaduttini"],"correctAnswer":"haakuttini"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My expenses became more than I expected, I need to revise the budget.","wordBankItems":["Nanna","kharchu","naanu","nambida","kante","jaasthi","aayitu",",","budget","revise","maadabeku","."],"correctAnswer":"Nanna kharchu naanu nambida kante jaasthi aayitu , budget revise maadabeku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kharchu means?","options":["expense/expenditure","income","savings","profit"],"correctAnswer":"expense/expenditure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000048',1,'APPROVED','PUBLISHED',
'{"objectives":["Use vocabulary for petrol station and car garage in Kannada","Ask for fuel and maintenance services","Discuss car trouble in Kannada"],"explanation":{"intro":"Petrol station and garage vocabulary covers how to fuel a vehicle, ask for maintenance, and describe car problems in Kannada.","culturalNote":"Vehicle culture in Karnataka: two-wheelers are very common in Bengaluru — Honda Activa, Hero Splendor, Pulsar are popular models. Four-wheelers: Maruti Suzuki Baleno, Alto, Brezza (all designed partly in Bengaluru), Tata Nexon (EV), Hyundai Creta. EV trend: Bengaluru is rapidly adopting EVs — BESCOM (electricity company) is expanding charging infrastructure. Petrol stations: Indian Oil, HP (Hindustan Petroleum), BPCL (Bharat Petroleum), Reliance. Self-service vs attendant: most Indian petrol stations have attendants who pump petrol. Full tank: full maadu (fill it full). Fixed amount: X rupai petrol haaku (put X rupees worth of petrol). Garage: puncture shop (tyre puncture repair — very common roadside business), service center (service center), car wash (car wash). Traffic: two-wheelers often ride on footpaths during heavy traffic — frowned upon but common. Helmets: helmet compulsory — traffic police check."},"examples":[{"sentence":"Elli ondhu petrol bunk ide? Nanna bike full maadabeku.","english":"Where is a petrol station? I need to fill my bike full."},{"sentence":"Nanna car engine thumba sound maaduttide, mechanic hattira toogobeku.","english":"My car engine is making a lot of noise, I need to take it to the mechanic."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can handle a petrol station and garage in Kannada."}}',
'{"items":[{"word":"petrol bunk","translation":"petrol station","transliteration":"petrol bunk","pronunciation":"PE-trol BUNK","example":"petrol bunk elli ide?"},{"word":"full maadu","translation":"fill (the tank) full","transliteration":"full maadu","pronunciation":"ful MAA-du","example":"full maadiri"},{"word":"puncture","translation":"flat tyre/puncture","transliteration":"puncture","pronunciation":"PUNK-char","example":"puncture aagide"},{"word":"mechanic","translation":"mechanic/repairman","transliteration":"mechanic","pronunciation":"me-KAN-ik","example":"mechanic hattira"},{"word":"toogobeku","translation":"need to take (to someone/somewhere)","transliteration":"toogobeku","pronunciation":"too-GO-be-ku","example":"mechanic hattira toogobeku"},{"word":"engine","translation":"engine","transliteration":"engine","pronunciation":"EN-jin","example":"engine sound maaduttide"}]}',
'{"title":"Petrol bunk elli ide? — petrol station and garage vocabulary","pattern":"Petrol bunk elli ide? = Where is a petrol station? Full maadiri = please fill it full (informal). X rupai petrol haakiri = please put X rupees worth of petrol (formal). Puncture aagide = there is a puncture. Engine problem aagide = there is an engine problem. Mechanic hattira toogobeku = need to take (it) to the mechanic.","explanation":"Vehicle vocabulary in Kannada: petrol bunk (petrol station), diesel (diesel), engine oil (engine oil), tyre (tyre), brake (brake). Problems: puncture (flat tyre), engine sound (strange engine noise), brake failu (brake failure). Services: full maadu (fill up), oil change maadu (change oil), service maadu (do a service). Mechanic: mechanic / garaaj (garage). Cost: eshtu aagutte? (how much will it cost?). Waiting: eshtu time aagutte? (how long will it take?). Emergency: roadside assistance. Car hire: taxi / Ola / Uber (ride-hailing). Parking: park maadu (park the vehicle), parking thoNde (parking fine/trouble).","examples":[{"sentence":"Nanna bike puncture aagide, hattira puncture shop ide aa?","english":"My bike has a puncture, is there a puncture shop nearby?"},{"sentence":"Full tank maadiri, diesel — eshtu aagutte?","english":"Please fill the full tank, diesel — how much will it be?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"full maadu means?","options":["fill (the tank) full","do a full service","fill it halfway","check the full tank"],"correctAnswer":"fill (the tank) full"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Where is a petrol station? I need to fill my bike full.","options":["Elli ondhu petrol bunk ide? Nanna bike full maadabeku.","Elli ondhu petrol bunk ide? Nanna car full maadabeku.","Elli ondhu petrol bunk ide? Nanna bike half maadabeku.","Yaavaga ondhu petrol bunk ide? Nanna bike full maadabeku."],"correctAnswer":"Elli ondhu petrol bunk ide? Nanna bike full maadabeku."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna car engine thumba sound maaduttide, mechanic hattira ___ .","options":["toogobeku","hogobeku","koDabeku","nodabeku"],"correctAnswer":"toogobeku"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My bike has a puncture, is there a puncture shop nearby?","wordBankItems":["Nanna","bike","puncture","aagide",",","hattira","puncture","shop","ide","aa","?"],"correctAnswer":"Nanna bike puncture aagide , hattira puncture shop ide aa ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"mechanic means?","options":["mechanic/repairman","driver","attendant","engineer"],"correctAnswer":"mechanic/repairman"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000049',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a traditional Karnataka wedding in Kannada","Use shaadi vocabulary including ceremonies and rituals","Talk about attending weddings as a guest"],"explanation":{"intro":"Traditional Karnataka wedding vocabulary covers the main ceremonies, rituals, vocabulary for gifts and greetings, and how to describe attending a wedding in Kannada.","culturalNote":"Karnataka weddings: weddings (shaadi / maduve — maduve is the formal Kannada word) are elaborate multi-day events. Key ceremonies: (1) Dhaareshina (the main ritual — bride''s father pours water into the groom''s hands while giving the bride in marriage — dharashana = giving by pouring). (2) Kaashi Yaatre (groom pretends to go on pilgrimage, is stopped by bride''s family — symbolic ceremony — common in Brahmin and many other communities). (3) NaamakaaraNa (naming ceremony for newborn — but also used at some weddings). (4) Saptapadi (seven steps around the fire — Vedic ceremony). Different community weddings: Vokkaligas (major Karnataka farming community — large elaborate weddings), Lingayats (another large community — more direct ceremonies), Brahmin weddings (Vedic Sanskrit rituals), Muslim weddings (Nikah), Christian weddings (church ceremony). All communities: food is the centrepiece — the wedding feast (maduve oota) is celebrated. Neem leaves (bevu) and mango leaves (maavinakkayi) decorations at the wedding gate are traditional."},"examples":[{"sentence":"Naale nanna mitrara maduve ide, naanu gift toogobeku.","english":"Tomorrow is my friend''s wedding, I need to take a gift."},{"sentence":"Maduve oota thumba channa itu — obbattu, bisi bele bath, payasa eradu thara itu.","english":"The wedding food was very good — there was obbattu, bisi bele bath, and two types of payasa."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe and discuss a traditional Karnataka wedding in Kannada."}}',
'{"items":[{"word":"maduve","translation":"wedding (formal Kannada)","transliteration":"maduve","pronunciation":"MA-du-ve","example":"maduve ide"},{"word":"shaadi","translation":"wedding (colloquial — from Urdu)","transliteration":"shaadi","pronunciation":"SHAA-di","example":"shaadi maaduttaare"},{"word":"vadhu","translation":"bride","transliteration":"vadhu","pronunciation":"VA-dhu","example":"channa vadhu"},{"word":"vara","translation":"groom","transliteration":"vara","pronunciation":"VA-ra","example":"vara baruttaane"},{"word":"payasa","translation":"sweet milk pudding (rice/vermicelli)","transliteration":"payasa","pronunciation":"pa-YA-sa","example":"payasa kodi"},{"word":"nimantrana","translation":"invitation","transliteration":"nimantrana","pronunciation":"ni-MAN-tra-na","example":"nimantrana tande"}]}',
'{"title":"Maduve nimantrana — wedding invitation vocabulary in Kannada","pattern":"X maduve ide = there is X''s wedding. Nimantrana tande = brought an invitation. X ge maduve shaadi aagutte = X is getting married. Gift toogobeku = need to take a gift. Maduve oota = wedding feast. Aasheervaada kodi = give blessings. Shubhaashayagalu = congratulations/best wishes (used at weddings).","explanation":"Wedding vocabulary in Kannada: maduve (wedding — formal), shaadi (wedding — colloquial), vadhu (bride), vara (groom), nimantrana (invitation), aasheervaada (blessing). Ceremonies: Dhaareshina (main ceremony), Kaashi Yatre (groom''s mock pilgrimage), Saptapadi (seven steps). Decorations: torana (garland at door — mango leaves), rangoli (kolam at entrance). Wedding food: obbattu (sweet flatbread), payasa (sweet pudding), kosambri (raw vegetable salad), hasi kayi kaayipalya (fresh vegetable side dish). Greeting the couple: shubhaashayagalu kodi (give best wishes — formal greeting at wedding). Gift: shaadi gift (wedding gift). Stage: vedike (stage/platform — vedike mele = on the stage).","examples":[{"sentence":"Avara maduve nimantrana naanu tande, shani vaara ee shaadi ide.","english":"I brought their wedding invitation, the wedding is this Saturday."},{"sentence":"Maduve alli naalidevi heLidaaga naakke thumba aananada aayitu.","english":"When they announced the bride''s name at the wedding, I felt very joyful."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"maduve means?","options":["wedding (formal Kannada)","party","celebration","festival"],"correctAnswer":"wedding (formal Kannada)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow is my friend''s wedding, I need to take a gift.","options":["Naale nanna mitrara maduve ide, naanu gift toogobeku.","Ninne nanna mitrara maduve itu, naanu gift toogobeku.","Naale nanna mitrara maduve ide, avaru gift toogobeku.","Naale nanna geleyana maduve ide, naanu gift toogobeku."],"correctAnswer":"Naale nanna mitrara maduve ide, naanu gift toogobeku."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Maduve oota thumba channa itu — obbattu, bisi bele bath, ___ eradu thara itu.","options":["payasa","saaru","huli","palya"],"correctAnswer":"payasa"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I brought their wedding invitation, the wedding is this Saturday.","wordBankItems":["Avara","maduve","nimantrana","naanu","tande",",","shani","vaara","ee","shaadi","ide","."],"correctAnswer":"Avara maduve nimantrana naanu tande , shani vaara ee shaadi ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"nimantrana means?","options":["invitation","blessing","gift","greeting"],"correctAnswer":"invitation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004a',1,'APPROVED','PUBLISHED',
'{"objectives":["Master Kannada number expressions for large amounts","Express hundreds, thousands, and lakhs in Kannada","Use ordinal numbers and fractions"],"explanation":{"intro":"Kannada number expressions covers large numbers — hundreds, thousands, lakhs — as well as ordinal numbers (first, second, etc.) and fractions useful for everyday calculations.","culturalNote":"Number system in Karnataka: India uses the lakh-crore system rather than the million-billion system. 1 lakh = 100,000. 1 crore = 10 million (100 lakhs). Property prices, salaries, and financial discussions all use lakhs and crores. Key Kannada numbers: nooru = 100, ondu saavira = 1,000, hattu saavira = 10,000, ondu lakh = 100,000 (1 lakh). Salary: ''my salary is 50k'' = naana sambhavana aidu hattu saavira (50,000). Property: ''the apartment costs 80 lakhs'' = ee apartment enbhattu lakh aagutte. Kannada-English number code-switching: urban Kannadigas freely say ''fifty lakhs'' (English) even in Kannada conversation, or ''ondu crore'' mixing Kannada ondu with English crore. Score in cricket: 50 runs = aimpattu runs. Date/calendar: month and day using numbers. Year (varsha): ondu saavira ombainooraippattu ondu (2021 — said digit by digit informally, or as a full word)."},"examples":[{"sentence":"Ee apartment enbhattu lakh aagutte, thumba jaasthi aagutte naakke.","english":"This apartment costs 80 lakhs, it is too much for me."},{"sentence":"Bengaluru alli ondu hajar square foot manege saathu aidu hattu lakh aagutte.","english":"A 1000 square foot house in Bengaluru costs approximately 50-60 lakhs."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express large numbers, lakhs, ordinals, and fractions in Kannada."}}',
'{"items":[{"word":"nooru","translation":"hundred (100)","transliteration":"nooru","pronunciation":"NOO-ru","example":"nooru rupai"},{"word":"saavira","translation":"thousand (1,000)","transliteration":"saavira","pronunciation":"SAA-vi-ra","example":"ondu saavira"},{"word":"lakh","translation":"lakh (100,000)","transliteration":"lakh","pronunciation":"lakh","example":"aidu lakh"},{"word":"crore","translation":"crore (10 million)","transliteration":"crore","pronunciation":"kror","example":"ondu crore"},{"word":"modalaneya","translation":"first (ordinal)","transliteration":"modalaneya","pronunciation":"mo-da-LA-ne-ya","example":"modalaneya sala"},{"word":"eraDeya","translation":"second (ordinal)","transliteration":"eraDeya","pronunciation":"e-RA-De-ya","example":"eraDeya barisi"}]}',
'{"title":"Nooru, saavira, lakh, crore — number expressions in Kannada","pattern":"100 = nooru, 1000 = ondu saavira, 10000 = hattu saavira, 100000 = ondu lakh, 1 crore = ondu crore. Ordinals: modalaneya (first), eraDeya (second), mooradaneya (third), naalkanEya (fourth), aidaney (fifth). Fractions: aradhu (half), mukkaal (three-quarters), kaal (quarter). Mixed: ondu saavira ombainooraippattu = 1,950 (thousand + 950).","explanation":"Kannada number system: ones: ondu, eradu, mooru, naalku, aidu, aaru, yelu, yenTu, ombattu, hattu. Tens: hattu (10), ipattu (20), moovattu (30), nalavattu (40), aimpattu (50), aravaattu (60), eppattu (70), embhatu (80), tombattu (90). Hundreds: nooru (100), eraDu nooru (200), mooru nooru (300). Large: saavira (1000), hattu saavira (10,000), ondu lakh (100,000), ondu crore (1 crore = 10 million). Ordinals: -aneya/-neya suffix: modalaneya (1st), eraDeya (2nd), mooradaneya (3rd), naalkaNeya (4th). Fractions: aradhu (half — 1/2), kaal (quarter — 1/4), mukkaal (3/4). Year: ee varsha = this year, munde varsha = next year, hinde varsha = last year.","examples":[{"sentence":"Naana sambhavana pratimaasa aidu hattu saavira rupai ide.","english":"My salary is 50,000 rupees per month."},{"sentence":"Nanna modalaneya kaelaa IT company alli itu, abhi eraDeya company alli iddini.","english":"My first job was at an IT company, now I am at a second company."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"lakh means?","options":["lakh (100,000)","thousand","million","crore"],"correctAnswer":"lakh (100,000)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"This apartment costs 80 lakhs, it is too much for me.","options":["Ee apartment enbhattu lakh aagutte, thumba jaasthi aagutte naakke.","Ee apartment tombattu lakh aagutte, thumba jaasthi aagutte naakke.","Ee apartment enbhattu lakh aagutte, thakku jaasthi aagutte naakke.","Ee maney enbhattu lakh aagutte, thumba jaasthi aagutte naakke."],"correctAnswer":"Ee apartment enbhattu lakh aagutte, thumba jaasthi aagutte naakke."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna ___ kaelaa IT company alli itu, abhi eraDeya company alli iddini.","options":["modalaneya","eraDeya","mooradaneya","naalkaNeya"],"correctAnswer":"modalaneya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My salary is 50,000 rupees per month.","wordBankItems":["Naana","sambhavana","pratimaasa","aidu","hattu","saavira","rupai","ide","."],"correctAnswer":"Naana sambhavana pratimaasa aidu hattu saavira rupai ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"modalaneya means?","options":["first (ordinal)","first time","first class","initially"],"correctAnswer":"first (ordinal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004b',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe Karnataka''s seasons and climate in Kannada","Talk about monsoon, summer, and winter in Kannada","Use seasonal vocabulary for clothes, activities, and food"],"explanation":{"intro":"Seasons vocabulary covers Karnataka''s distinct climate seasons, weather patterns, and how they affect daily life, clothing, and food choices.","culturalNote":"Karnataka''s climate: Karnataka has three main seasons — (1) Summer (Beshige — March to May): dry and hot. In North Karnataka plains: very hot (45°C+). Bengaluru: relatively cooler due to altitude (920m) — 25-35°C. Western Ghats: pleasant. Drinks: buttermilk (majjige), tender coconut (eLeNeeru), lemon water (nimbehannu neeru). (2) Monsoon (Varshakaala — June to September): Southwest monsoon arrives first in Karavali/Malnad (June 1 in Kerala, reaches Karnataka June 5-10). Very heavy rainfall in Coorg (Kodagu — 3500-5000mm). Bengaluru: moderate rain (800-900mm annually). Western Ghats get 3000-6000mm. Monsoon food: pakodas (bajji), chai. (3) Winter (Chaleegaala — November to February): pleasant in Bengaluru (15-25°C). Bengaluru winters are famous — people from Chennai and Hyderabad visit. Ooty, Kodagu: much cooler, occasional frost. Mysuru winter: Dasara season (October) — after monsoon ends."},"examples":[{"sentence":"Varshakaala alli Coorg alli thumba maLe barutte, hasi bana thumba channa aguttade.","english":"During monsoon in Coorg very much rain falls, the greenery is very beautiful."},{"sentence":"Bengaluru chaleegaala thumba channa aguttade — nannige aa ruthu hecchaagi ishtavagutte.","english":"Bengaluru''s winter is very nice — I prefer that season."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe Karnataka''s seasons, climate, and seasonal activities in Kannada."}}',
'{"items":[{"word":"beshige","translation":"summer/hot season","transliteration":"beshige","pronunciation":"BE-shi-ge","example":"beshige kaala"},{"word":"varshakaala","translation":"monsoon/rainy season","transliteration":"varshakaala","pronunciation":"var-sha-KAA-la","example":"varshakaala ide"},{"word":"chaleegaala","translation":"winter/cool season","transliteration":"chaleegaala","pronunciation":"cha-lee-GAA-la","example":"chaleegaala channa"},{"word":"challu","translation":"cold (temperature/weather)","transliteration":"challu","pronunciation":"CHAL-lu","example":"thumba challu"},{"word":"bisinappe","translation":"heat/hot weather","transliteration":"bisinappe","pronunciation":"bi-si-NAP-pe","example":"bisinappe jaasthi"},{"word":"hasi bana","translation":"greenery (lit. green colour)","transliteration":"hasi bana","pronunciation":"HA-si BA-na","example":"hasi bana channa"}]}',
'{"title":"Karnataka''s three seasons — beshige, varshakaala, chaleegaala","pattern":"Beshige = summer. Varshakaala = monsoon/rainy season (varsha = year/rain). Chaleegaala = winter (chali = cold, kaala = season/time). Current weather: inja beshige/challu/maLe ide (today it is summer/cold/rainy). Season activities: beshige alli X maaduttini (in summer I do X). Describing seasonal change: beshiga nantara varshakaala baruttade (after summer, monsoon comes).","explanation":"Season vocabulary in Kannada: beshige/beshigaala (hot season/summer), varshakaala (rainy season/monsoon), chaleegaala (winter/cold season). Weather during: bisinappe (heat), challu (cold), maLe (rain). Activities: beshige alli ice cream tinuttini (in summer I eat ice cream), varshakaala alli bajji tinuttini (in monsoon I eat bajji), chaleegaala alli sweater haakuttini (in winter I wear a sweater). Bengaluru exception: Bengaluru has no extreme seasons — hence the name ''Garden City'' and why many people prefer to live there. Common phrases: inja haage thumba bisinappe ide (today the heat is so much), varshakaala bardarbeekaagi (because the monsoon came), chaleegaala channa aguttade (winter is pleasant).","examples":[{"sentence":"Chaleegaala alli Bengaluru alli hawaa thumba channa aguttade, bisinappe illaa.","english":"In winter the weather in Bengaluru is very nice, there is no heat."},{"sentence":"Varshakaala alli naakke bajji haagu chai thumba ishtavagutte.","english":"In the monsoon I really like bajji and chai."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"varshakaala means?","options":["monsoon/rainy season","winter","summer","spring"],"correctAnswer":"monsoon/rainy season"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"During monsoon in Coorg very much rain falls, the greenery is very beautiful.","options":["Varshakaala alli Coorg alli thumba maLe barutte, hasi bana thumba channa aguttade.","Chaleegaala alli Coorg alli thumba maLe barutte, hasi bana thumba channa aguttade.","Varshakaala alli Bengaluru alli thumba maLe barutte, hasi bana thumba channa aguttade.","Varshakaala alli Coorg alli thakku maLe barutte, hasi bana thumba channa aguttade."],"correctAnswer":"Varshakaala alli Coorg alli thumba maLe barutte, hasi bana thumba channa aguttade."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Chaleegaala alli Bengaluru alli hawaa thumba channa aguttade, ___ illaa.","options":["bisinappe","challu","maLe","varshakaala"],"correctAnswer":"bisinappe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the monsoon I really like bajji and chai.","wordBankItems":["Varshakaala","alli","naakke","bajji","haagu","chai","thumba","ishtavagutte","."],"correctAnswer":"Varshakaala alli naakke bajji haagu chai thumba ishtavagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"challu means?","options":["cold (temperature/weather)","hot","rain","wind"],"correctAnswer":"cold (temperature/weather)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004c',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe your neighborhood in Kannada","Use neighbourhood vocabulary for local amenities","Talk about what is near your house"],"explanation":{"intro":"Describing your neighborhood covers how to talk about what is near your home, the facilities available, and the character of your local area in Kannada.","culturalNote":"Neighborhood culture in Karnataka: in Bengaluru, neighborhoods (ooru/area/layout) have specific characters. Old Bengaluru neighborhoods: Malleshwaram (old Bengaluru — traditional, temples, Brahmin-dominated, famous for Udipi hotels), Basavanagudi (Bull Temple area — old Bengaluru culture), Rajajinagar (middle class — well-planned). New Bengaluru: Whitefield (IT corridor — international companies), Electronic City (IT hub — far south), Koramangala (startup hub — young professionals, cafes, pubs), Indiranagar (upmarket — bars, restaurants, boutiques), HSR Layout (planned — young families), JP Nagar (middle class, South). Traditional neighborhood elements: temple (gudi/devalaya), community well (baavigu — old-style), playground (aaTa sthala), grocery (angaDi), dairy/milk booth (haalu angaDi). Apartment vs independent house: rapidly shifting to apartment culture. Gated community (gated community — English term used)."},"examples":[{"sentence":"Namma area alli ondu channa park ide, pratidinaa beLigge avalli naaDuttini.","english":"In our area there is a nice park, every morning I walk there."},{"sentence":"Namma padatte mane hattira ondu supermarket, school haagu hospital ide.","english":"Near our neighboring house there is a supermarket, school and hospital."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my neighborhood and local area in Kannada."}}',
'{"items":[{"word":"area","translation":"area/neighborhood","transliteration":"area","pronunciation":"EE-ri-ya","example":"namma area"},{"word":"padatte mane","translation":"neighboring house/next door","transliteration":"padatte mane","pronunciation":"pa-DAT-te MA-ne","example":"padatte mane manushya"},{"word":"park","translation":"park","transliteration":"park","pronunciation":"paark","example":"park alli naaDuttini"},{"word":"supermarket","translation":"supermarket","transliteration":"supermarket","pronunciation":"SU-par-maar-ket","example":"supermarket hattira"},{"word":"gudi","translation":"temple","transliteration":"gudi","pronunciation":"GU-di","example":"namma area gudi"},{"word":"koLageri","translation":"drainage/drainage area (a common neighborhood feature)","transliteration":"koLageri","pronunciation":"ko-La-GE-ri","example":"koLageri hattira"}]}',
'{"title":"Namma area alli — describing your neighborhood in Kannada","pattern":"Namma area alli X ide = there is X in our area. X hattira Y ide = near X there is Y. X inda Y saaLu/naDeyaLa dooRadalli = X is walking distance from Y. Walking distance: naaDakke X nimisha (X minutes walking). Bus stop: bus stop hattira ide (near the bus stop). Metro: metro station hattira ide (near the metro station). Shops: angaDi, supermarket, bakery. Services: hospital, school, police station, post office.","explanation":"Neighborhood vocabulary in Kannada: area (area/locality), layout (planned neighborhood — a Bengaluru term), colony (residential area), namma ooru (our town/village). Features: gudi (temple), masjid (mosque), church (church), park (park), school (school), hospital (hospital), angaDi (shop), supermarket (supermarket), bus stop (bus stop), metro station (metro station). Distances: hattirage ide (it is nearby), dooradalli ide (it is far), naaDakke X nimisha (X minutes walking). Describing quality: shanta area (quiet area), jaasthi traffic (lots of traffic), hasi/hasira jagagaLu (green spaces), suthtamuttala channa (surroundings are nice).","examples":[{"sentence":"Namma apartment inda school hattu nimisha naaDaLa dooradalli ide.","english":"The school is 10 minutes walking distance from our apartment."},{"sentence":"Namma area alli thumba traffic aagutte, aadare park haagu gudi hattira ide.","english":"In our area there is a lot of traffic, but the park and temple are nearby."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"padatte mane means?","options":["neighboring house/next door","apartment","house nearby","house behind"],"correctAnswer":"neighboring house/next door"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In our area there is a nice park, every morning I walk there.","options":["Namma area alli ondu channa park ide, pratidinaa beLigge avalli naaDuttini.","Namma area alli eradu channa park ide, pratidinaa beLigge avalli naaDuttini.","Namma area alli ondu channa gudi ide, pratidinaa beLigge avalli naaDuttini.","Avara area alli ondu channa park ide, pratidinaa beLigge avalli naaDuttini."],"correctAnswer":"Namma area alli ondu channa park ide, pratidinaa beLigge avalli naaDuttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma apartment inda school hattu nimisha ___ dooradalli ide.","options":["naaDaLa","hogaLa","baDaLa","saaLa"],"correctAnswer":"naaDaLa"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Near our neighboring house there is a supermarket, school and hospital.","wordBankItems":["Namma","padatte","mane","hattira","ondu","supermarket",",","school","haagu","hospital","ide","."],"correctAnswer":"Namma padatte mane hattira ondu supermarket , school haagu hospital ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"gudi means?","options":["temple","park","hospital","school"],"correctAnswer":"temple"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004d',1,'APPROVED','PUBLISHED',
'{"objectives":["Express surprise and curiosity in Kannada","Use aree! and eno idu! as exclamations","Ask curious questions with yaavudu, hege, yaakelendare"],"explanation":{"intro":"Expressing surprise and curiosity covers exclamations, question phrases for exploring unknown things, and how to show interest and amazement in Kannada.","culturalNote":"Surprise and curiosity in Karnataka culture: Kannadigas are known for expressing themselves through rich exclamatory language, often mixing Kannada and English. Surprise exclamations: aree! (surprise — like ''oh!''), eno idu! (what is this!), ayyo! (dismay/shock — shared across South Indian languages). Curiosity: asking questions is a virtue in Kannada culture — asking a shopkeeper, a stranger on the road, an elder — all considered normal. Gossiping (adde maatnaaDu) is a social activity — especially among elderly people in parks (gandhinagar morning walkers). Kannada TV serials: soap operas are hugely popular — they feature many dramatic exclamations and plot twists that mirror these surprise expressions. Gossip culture: ''eno heLuttini nimage'' (let me tell you something) is a common way to start sharing information. Nosy/curious vs genuinely interested: there is a difference in Kannada between curious (jignyaase) and interfering (haLaseyu/haLaseyuvudu)."},"examples":[{"sentence":"Aree! Neevu illi iddiri aa? Naanu nimage noduttini anta nambilla!","english":"Oh wow! You were here? I didn''t even expect to see you!"},{"sentence":"Eno idu! Ee tantra yaavudu? Naakke thumba jignyaase aagutte.","english":"What is this! What is this technology? I am very curious."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express surprise and curiosity naturally in Kannada."}}',
'{"items":[{"word":"aree","translation":"oh!/wow!/exclamation of surprise","transliteration":"aree","pronunciation":"a-REE","example":"aree! hege itu?"},{"word":"ayyo","translation":"oh no!/alas!/exclamation of dismay","transliteration":"ayyo","pronunciation":"AY-yo","example":"ayyo! hogitu!"},{"word":"jignyaase","translation":"curiosity/interest in knowing","transliteration":"jignyaase","pronunciation":"jig-NYAA-se","example":"naakke jignyaase ide"},{"word":"eno idu","translation":"what is this!/exclamation of amazement","transliteration":"eno idu","pronunciation":"e-NO I-du","example":"eno idu! channa!"},{"word":"nishchayavaagi","translation":"definitely/certainly","transliteration":"nishchayavaagi","pronunciation":"NISH-cha-ya-VAA-gi","example":"nishchayavaagi baruttini"},{"word":"hege aayitu","translation":"how did this happen?/how was it?","transliteration":"hege aayitu","pronunciation":"HE-ge AA-yi-tu","example":"hege aayitu ninge?"}]}',
'{"title":"Aree! Eno idu! — exclamations of surprise and curiosity in Kannada","pattern":"Aree! = Wow!/Oh! (positive/neutral surprise). Ayyo! = Oh no! (negative surprise or dismay). Eno idu! = What is this! (amazement). Jignyaase: naakke X jignyaase ide = I am curious about X. Questions of curiosity: hege? (how?), yaakelendare? (why? — asking for reason), yaavudu idu? (what is this?), yaaru avaru? (who is that?). Response to surprise: naakke nambilaa (I couldn''t believe it!).","explanation":"Surprise and curiosity in Kannada: exclamations: aree! (positive surprise — like ''wow!''), ayyo! (negative surprise — like ''oh no!''). Strong surprise: eno idu! (what is this!), aaraa (informal — oh really?), ide-e (elongated — expressing wonder). Curiosity questions: naakke X bagge jignyaase ide (I am curious about X — bagge = about). Asking more: hecchaagi heLi (tell me more — hecchaagi = more, heLi = tell). Disbelief: naakke nambilaa (I can''t believe it). Amazement at skill: avarigu hege gottitu! (how did they know! — gottitu = knew/found out). Setting up story: enu gottaa? (do you know what? — common way to start an exciting story).","examples":[{"sentence":"Ayyo! Naanna wallet hogide! Hege aayitu?","english":"Oh no! My wallet is gone! How did this happen?"},{"sentence":"Aree! Enu gottaa? Nanna geleya IIT ge select aadaane!","english":"Oh wow! Do you know what? My friend got selected for IIT!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"jignyaase means?","options":["curiosity/interest in knowing","surprise","shock","wonder"],"correctAnswer":"curiosity/interest in knowing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Oh wow! You were here? I didn''t even expect to see you!","options":["Aree! Neevu illi iddiri aa? Naanu nimage noduttini anta nambilla!","Ayyo! Neevu illi iddiri aa? Naanu nimage noduttini anta nambilla!","Aree! Avaru illi iddaare aa? Naanu avarigu noduttini anta nambilla!","Aree! Neevu illi iddiri aa? Avaru nimage noduttini anta nambilla!"],"correctAnswer":"Aree! Neevu illi iddiri aa? Naanu nimage noduttini anta nambilla!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ayyo! Naanna wallet hogide! ___ aayitu?","options":["hege","yaake","yaavaga","yaaru"],"correctAnswer":"hege"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Oh wow! Do you know what? My friend got selected for IIT!","wordBankItems":["Aree","!","Enu","gottaa","?","Nanna","geleya","IIT","ge","select","aadaane","!"],"correctAnswer":"Aree ! Enu gottaa ? Nanna geleya IIT ge select aadaane !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"eno idu means?","options":["what is this!/exclamation of amazement","what happened","where is this","who is this"],"correctAnswer":"what is this!/exclamation of amazement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004e',1,'APPROVED','PUBLISHED',
'{"objectives":["Use airport and travel preparation vocabulary in Kannada","Check in, go through security, and board a flight in Kannada","Discuss travel documents and packing in Kannada"],"explanation":{"intro":"Airport and travel preparation vocabulary covers how to navigate an airport, discuss flights, check in, and prepare for domestic and international travel using Kannada.","culturalNote":"Air travel in Karnataka: Kempegowda International Airport Bengaluru (BLR/KIAL) — opened 2008, handles 33 million passengers annually, India''s third-busiest. Named after Kempe Gowda I (the founder of Bengaluru — a 16th century chieftain). Second airport: HAL Airport (the old airport — now for chartered flights and military). Airlines: IndiGo (largest domestic), Air India (government/Tata), Vistara (Tata), SpiceJet. International flights: BLR connects to Dubai (Emirates, Air Arabia), Singapore (Singapore Airlines), Frankfurt, London Heathrow, New York (JFK), Bangkok, Malaysia, etc. Metro to airport: Namma Metro Purple Line now extends to airport. Airport facilities: Bengaluru Airport''s Terminal 2 (T2) opened 2023 — has a vertical garden (5km long — world''s longest). Duty-free (duty free shop). VIP lounge (club/lounge access). Prepaid taxi at airport."},"examples":[{"sentence":"Naale naanu Dubai ge hoguttini, beLigge aaru gante flight ide.","english":"Tomorrow I am going to Dubai, there is a flight at 6 AM."},{"sentence":"Check-in counter elli ide? Naanna passport haagu boarding pass ready ide.","english":"Where is the check-in counter? My passport and boarding pass are ready."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate an airport and discuss air travel in Kannada."}}',
'{"items":[{"word":"vibmaana","translation":"airplane","transliteration":"vibmaana","pronunciation":"vi-MAA-na","example":"vibmaana alli hoguttini"},{"word":"passport","translation":"passport","transliteration":"passport","pronunciation":"PAAS-port","example":"passport ready ide"},{"word":"check-in","translation":"check-in (airport)","transliteration":"check-in","pronunciation":"chek-IN","example":"check-in maadabeku"},{"word":"boarding pass","translation":"boarding pass","transliteration":"boarding pass","pronunciation":"BOR-ding paas","example":"boarding pass kodi"},{"word":"luggage","translation":"luggage/bags","transliteration":"luggage","pronunciation":"LUG-ij","example":"luggage heavy ide"},{"word":"gate","translation":"boarding gate","transliteration":"gate","pronunciation":"gayt","example":"gate number eshtu?"}]}',
'{"title":"Vibmaana alli hoguttini — airport vocabulary in Kannada","pattern":"Naanu vibmaana alli hoguttini = I am going by airplane. Check-in maadabeku = need to check in. Passport/visa ready ide = passport/visa is ready. Luggage: luggage check-in maadabeku (check in luggage). Security: security check aguttide (security check is happening). Boarding: ee gate inda board maaduttini (I am boarding from this gate).","explanation":"Airport vocabulary in Kannada: vibmaana (airplane — from Sanskrit vimana = flying vehicle), uddata vibmaana (flying airplane). Flight: flight (used directly), vibmaana haara (airplane route). Check-in: check-in counter elli ide? (where is the check-in counter?). Luggage: check-in luggage (checked bag), hand luggage (cabin bag). Delay: flight delay aagide (flight is delayed). Cancelled: flight cancel aagide. Security: security check (security screening). Boarding: boarding shuru aayitu (boarding has started). Gate: yaava gate inda? (from which gate?). Arrival: vibmaana ilikide (airplane has landed — ilikide = has landed). Customs (customs — for international travel). Immigration (immigration counter).","examples":[{"sentence":"Naanna flight Mumbai ge hoguttide, aadare thumba delay aagide.","english":"My flight is going to Mumbai, but there is a lot of delay."},{"sentence":"Security check nantara Gate 7 ge hogi, boarding pass scan maadiri.","english":"After security check go to Gate 7, please scan the boarding pass."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"vibmaana means?","options":["airplane","train","bus","vehicle"],"correctAnswer":"airplane"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow I am going to Dubai, there is a flight at 6 AM.","options":["Naale naanu Dubai ge hoguttini, beLigge aaru gante flight ide.","Inja naanu Dubai ge hoguttini, beLigge aaru gante flight ide.","Naale naanu Singapore ge hoguttini, beLigge aaru gante flight ide.","Naale avanu Dubai ge hoguttaane, beLigge aaru gante flight ide."],"correctAnswer":"Naale naanu Dubai ge hoguttini, beLigge aaru gante flight ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Check-in counter elli ide? Naanna ___ haagu boarding pass ready ide.","options":["passport","luggage","gate","ticket"],"correctAnswer":"passport"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: After security check go to Gate 7, please scan the boarding pass.","wordBankItems":["Security","check","nantara","Gate","7","ge","hogi",",","boarding","pass","scan","maadiri","."],"correctAnswer":"Security check nantara Gate 7 ge hogi , boarding pass scan maadiri ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"gate means?","options":["boarding gate","door","entrance","exit"],"correctAnswer":"boarding gate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000004f',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about childhood memories in Kannada","Use hannu tana (childhood) vocabulary","Recall past events with the past tense and time expressions"],"explanation":{"intro":"Childhood memories covers vocabulary and grammar for sharing memories from your early years, describing how things were different, and expressing nostalgia in Kannada.","culturalNote":"Childhood in Karnataka: the concept of ''ooru'' (hometown village) is central to Kannada identity. Many urban Kannadigas were born in villages or small towns and moved to Bengaluru for education/work. ''Namma ooru'' (our hometown) — always spoken of with warmth and nostalgia. Childhood memories: grandmother''s stories (ajji kathai), playing in the mud (maNNalli aaduvudu), climbing mango trees (mavinakaayi mara haththuvudu), summer visits to grandparents'' village (ajja-ajji mane), participating in festivals, drawing rangoli, playing traditional games (lagori, kambala). Traditional games (aaTa): katte aaTa (stone games), lippu aaTa (skipping rope), goli (marbles), kambala (traditional water buffalo racing), Kabaddi (naational sport). Village childhood: collecting firewood (kuppa), fetching water from well (baavigu neeru), playing in fields. Urban childhood: playing video games, cricket in the street, going to school by auto."},"examples":[{"sentence":"Naanna hannu tana namma ooru alli kaTTiyade, mavinakayi mara hattuttidde.","english":"My childhood was at our hometown, I used to climb mango trees."},{"sentence":"Naanna ajji maneyalli beSiga raatrisu kathe heLuttidaLe — avara kathe naakke thumba ishtavaagidutte.","english":"My grandmother used to tell stories in the night during summer — I really used to like her stories."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about childhood memories and nostalgic experiences in Kannada."}}',
'{"items":[{"word":"hannu tana","translation":"childhood (lit. fruit-time — blossom years)","transliteration":"hannu tana","pronunciation":"HAN-nu TA-na","example":"naanna hannu tana"},{"word":"ooru","translation":"hometown/village","transliteration":"ooru","pronunciation":"OO-ru","example":"namma ooru"},{"word":"ajji","translation":"grandmother","transliteration":"ajji","pronunciation":"AJ-ji","example":"naanna ajji"},{"word":"ajja","translation":"grandfather","transliteration":"ajja","pronunciation":"AJ-ja","example":"naanna ajja"},{"word":"idde","translation":"used to be (imperfect/habitual past — 1st person)","transliteration":"idde","pronunciation":"ID-de","example":"naanu alli idde"},{"word":"heLuttidaLe","translation":"used to tell/say (habitual past — 3rd person feminine)","transliteration":"heLuttidaLe","pronunciation":"he-LUT-ti-da-Le","example":"kathe heLuttidaLe"}]}',
'{"title":"Naanna hannu tana — talking about childhood in Kannada","pattern":"Naanna hannu tana = my childhood. Naanu X maaduttidde = I used to do X (habitual past — -uttidde = used to do). Hinde (in the past/before — hinde = back). Past location: naanu X alli idde (I used to be at X). Grandmother''s habit: ajji X heLuttidaaLe (grandmother used to tell/say X). Comparing now and then: hinde X aagiutte itu, abhi Y aagutte (earlier it used to be X, now it is Y).","explanation":"Childhood memories in Kannada: hannu tana (childhood — from hannu = fruit, tana = time/state — the time of blossoming). Past habitual (''used to''): verb + uttidde (1st person singular), uttidaane (3rd masc), uttidaaLe (3rd fem), uttidaare (3rd formal). Examples: naanu X maaduttidde (I used to do X), avanu Y heLuttidaane (he used to say Y). Comparison then/now: hinde X aagiutte itu, abhi Y aagutte. Nostalgic expressions: naaLugaLu channa itu (those days were good — naaLugaLu = those days), miss aagutte (I miss it). How things were: illi thumba hasi aagirutte itu (it used to be very green here).","examples":[{"sentence":"Naanu hannu tanada alli pratidinaa school nantara huli mara hattuttidde.","english":"In childhood I used to climb tamarind trees every day after school."},{"sentence":"Namma oooru hinde thumba shanta aagiutte itu, abhi jaasthi traffic ide.","english":"Our hometown used to be very quiet, now there is a lot of traffic."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ajji means?","options":["grandmother","grandfather","aunt","elder sister"],"correctAnswer":"grandmother"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My childhood was at our hometown, I used to climb mango trees.","options":["Naanna hannu tana namma ooru alli kaTTiyade, mavinakayi mara hattuttidde.","Naanna hannu tana namma ooru alli kaTTiyade, mavinakayi mara hattide.","Avana hannu tana namma ooru alli kaTTiyade, mavinakayi mara hattuttidde.","Naanna hannu tana avara ooru alli kaTTiyade, mavinakayi mara hattuttidde."],"correctAnswer":"Naanna hannu tana namma ooru alli kaTTiyade, mavinakayi mara hattuttidde."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma ooru hinde thumba shanta ___ , abhi jaasthi traffic ide.","options":["aagiutte itu","aagutte","aayitu","aguttade"],"correctAnswer":"aagiutte itu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My grandmother used to tell stories in the night during summer.","wordBankItems":["Naanna","ajji","maneyalli","beSiga","raatrisu","kathe","heLuttidaLe","."],"correctAnswer":"Naanna ajji maneyalli beSiga raatrisu kathe heLuttidaLe ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"idde means?","options":["used to be (habitual past — 1st person)","I was","I went","I used to go"],"correctAnswer":"used to be (habitual past — 1st person)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000050',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all major Karnataka cultural knowledge","Practice key Kannada sentences from lessons 1-79","Consolidate grammar patterns and cultural vocabulary"],"explanation":{"intro":"A1 Milestone — Culture and Language Review consolidates the cultural and linguistic knowledge from all A1 lessons with a focus on Karnataka identity, important vocabulary, and core sentences.","culturalNote":"What you know after Kannada A1: Language: Kannada greetings (Namaskara, hege iddiri?), introductions, family terms, numbers 1 to crore, directions, questions (yaaru, enu, elli, yaavaga, eshtu, hege), time expressions, daily routines, feelings, comparisons. Culture: Bengaluru (Garden City, IT hub), Mysuru (City of Palaces, Dasara), Karnataka geography (31 districts, Western Ghats, Kaveri), food (filter kaapi, dosa, saaru, palya, bisi bele bath, obbattu, Mysuru pak), festivals (Dasara, Ugaadi, Makara Sankranti), arts (Yakshagana, Dollu Kunitha, Bharatanatyam), cricket (Karnataka Ranji, RCB), cinema (Sandalwood — Puneeth Rajkumar, KGF), nature (Bandipur, Nagarhole, Western Ghats). Social etiquette: formal/informal register (neevu/neenu), gratitude (dhanyavadagalu), polite requests (dayavittu), invitation culture. A1 complete: neevu Kannada A1 poorthi maadiddiri! A2 alli hecchaagi kalivona!"},"examples":[{"sentence":"Namaskara! Naanu Bengaluru inda. Neevu? Karnataka alli hosthavar aa?","english":"Hello! I am from Bengaluru. You? Are you new to Karnataka?"},{"sentence":"Neevu Kannada A1 poorthi maadiddiri — shubhaashayagalu! A2 ge swaagata!","english":"You have completed Kannada A1 — congratulations! Welcome to A2!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed Kannada A1 with full cultural and linguistic knowledge — ready for A2!"}}',
'{"items":[{"word":"hosthavaru","translation":"newcomer/person new to a place","transliteration":"hosthavaru","pronunciation":"HOS-tha-va-ru","example":"Karnataka alli hosthavaru"},{"word":"swaagata","translation":"welcome","transliteration":"swaagata","pronunciation":"SWA-ga-ta","example":"swaagata kodi"},{"word":"shubhaashayagalu","translation":"congratulations/best wishes (formal)","transliteration":"shubhaashayagalu","pronunciation":"shub-haash-a-ya-GA-lu","example":"shubhaashayagalu nimge"},{"word":"poorthi","translation":"complete/finished","transliteration":"poorthi","pronunciation":"POOR-thi","example":"A1 poorthi aayitu"},{"word":"kalivona","translation":"let''s learn (together — 1st plural inclusive)","transliteration":"kalivona","pronunciation":"ka-li-VO-na","example":"koodi kalivona"},{"word":"hosatana","translation":"novelty/freshness/newness","transliteration":"hosatana","pronunciation":"ho-SA-ta-na","example":"hosatana anubhava"}]}',
'{"title":"Kannada A1 poorthi — culture and language milestone review","pattern":"X poorthi aayitu = X is completed. Swaagata! = Welcome! Shubhaashayagalu! = Congratulations! Kalivona = let''s learn. Koodi hogona = let''s go together. A1 key patterns: Namaskara (hello), naanu X iddini (I am X), naakke X beku (I need X), X maaduttini (I do X), hege iddiri? (how are you? — formal), dhanyavadagalu (thank you), dayavittu (please), howdu/illa (yes/no).","explanation":"A1 complete cultural knowledge checklist: Language skills: greet, introduce, buy at market (eshtu aagutte?/kodi), take bus/train/auto, find directions (nera/bala/yele), visit doctor (naakke novu ide), invite and accept/decline, express feelings (naakke santosha aagutte), compare things (X ginta Y channa), discuss weather (beshige/varshakaala/chaleegaala), talk about job and hobbies. Cultural knowledge: Karnataka''s geography (31 districts, Western Ghats, Kaveri), Bengaluru (IT hub), Mysuru (Dasara), food (filter kaapi, saaru, palya, bisi bele bath), arts (Yakshagana, Dollu Kunitha), cricket (RCB), cinema (Sandalwood), social norms (formal/informal, invitation etiquette). You are ready for A2!","examples":[{"sentence":"Naanu Kannada A1 poorthi maadide — dhanyavadagalu Claude!","english":"I have completed Kannada A1 — thank you Claude!"},{"sentence":"A2 alli anek hosatana shabd haagu grammar kaliyuttevi — koodi hogona!","english":"In A2 we will learn many new words and grammar — let''s go together!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"poorthi means?","options":["complete/finished","start","middle","end"],"correctAnswer":"complete/finished"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello! I am from Bengaluru. You? Are you new to Karnataka?","options":["Namaskara! Naanu Bengaluru inda. Neevu? Karnataka alli hosthavar aa?","Namaskara! Naanu Mysuru inda. Neevu? Karnataka alli hosthavar aa?","Namaskara! Naanu Bengaluru inda. Avaru? Karnataka alli hosthavar aa?","Namaskara! Naanu Bengaluru inda. Neevu? Karnataka inda hosthavar aa?"],"correctAnswer":"Namaskara! Naanu Bengaluru inda. Neevu? Karnataka alli hosthavar aa?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu Kannada A1 poorthi maadide — ___ Claude!","options":["dhanyavadagalu","Namaskara","swaagata","shubhaashayagalu"],"correctAnswer":"dhanyavadagalu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You have completed Kannada A1 — congratulations! Welcome to A2!","wordBankItems":["Neevu","Kannada","A1","poorthi","maadiddiri","—","shubhaashayagalu","!","A2","ge","swaagata","!"],"correctAnswer":"Neevu Kannada A1 poorthi maadiddiri — shubhaashayagalu ! A2 ge swaagata !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kalivona means?","options":["let''s learn (together)","I will learn","you learn","learn!"],"correctAnswer":"let''s learn (together)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

